=== src/main/java/pousada/domain/identification/IdentificationKinds.java
     1	package pousada.domain.identification;
     2	
     3	import pousada.domain.DomainException;
     4	
     5	import java.util.ArrayList;
     6	import java.util.LinkedHashMap;
     7	import java.util.List;
     8	import java.util.Map;
     9	
    10	/** Registro das formas de identificação: é o único lugar a mexer para aceitar uma nova. */
    11	public final class IdentificationKinds {
    12	
    13	    private static final List<IdentificationKind> KINDS = List.of(
    14	            new CpfIdentification.Kind(),
    15	            new CnpjIdentification.Kind(),
    16	            new PassportIdentification.Kind());
    17	
    18	    private IdentificationKinds() {
    19	    }
    20	
    21	    /** Todos os campos de identificação, na ordem em que aparecem no JSON. */
    22	    public static List<String> allFieldNames() {
    23	        List<String> names = new ArrayList<>();
    24	        KINDS.forEach(kind -> names.addAll(kind.fieldNames()));
    25	        return names;
    26	    }
    27	
    28	    /** {@code given} traz os campos presentes no corpo (valores nulos já descartados). */
    29	    public static Identification parse(Map<String, String> given) {
    30	        List<IdentificationKind> used = KINDS.stream()
    31	                .filter(kind -> kind.fieldNames().stream().anyMatch(given::containsKey))
    32	                .toList();
    33	        if (used.size() != 1) {
    34	            throw DomainException.invalidRequest(
    35	                    "Informe a identificação de um único jeito: " + describeKinds());
    36	        }
    37	        IdentificationKind kind = used.get(0);
    38	        Map<String, String> values = new LinkedHashMap<>();
    39	        for (String name : kind.fieldNames()) {
    40	            String value = given.get(name);
    41	            if (value == null || value.isBlank()) {
    42	                throw DomainException.invalidRequest("Campo obrigatório ausente: " + name);
    43	            }
    44	            values.put(name, value.trim());
    45	        }
    46	        return kind.create(values);
    47	    }
    48	
    49	    /** Mapa com todos os campos de identificação, null nos que não se aplicam. */
    50	    public static Map<String, String> withNulls(Identification identification) {
    51	        Map<String, String> all = new LinkedHashMap<>();
    52	        for (String name : allFieldNames()) {
    53	            all.put(name, identification.fields().get(name));
    54	        }
    55	        return all;
    56	    }
    57	
    58	    private static String describeKinds() {
    59	        return String.join(" | ", KINDS.stream().map(kind -> String.join("+", kind.fieldNames())).toList());
    60	    }
    61	}
