     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.Month;
     6	
     7	/** Preço da estadia: diária do quarto, acréscimo de alta temporada e desconto do plano. */
     8	public final class Pricing {
     9	
    10	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
    11	
    12	    private Pricing() {
    13	    }
    14	
    15	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    16	    }
    17	
    18	    public static boolean isHighSeason(LocalDate night) {
    19	        Month month = night.getMonth();
    20	        if (month == Month.JANUARY || month == Month.FEBRUARY || month == Month.JULY) {
    21	            return true;
    22	        }
    23	        return month == Month.DECEMBER && night.getDayOfMonth() >= 15;
    24	    }
    25	
    26	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    27	        BigDecimal subtotal = BigDecimal.ZERO;
    28	        int nights = 0;
    29	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    30	            subtotal = Money.round(subtotal.add(nightPrice(room, night)));
    31	            nights++;
    32	        }
    33	        BigDecimal discount = plan.discountOn(subtotal);
    34	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    35	    }
    36	
    37	    private static BigDecimal nightPrice(Room room, LocalDate night) {
    38	        if (isHighSeason(night)) {
    39	            return Money.round(room.nightlyRate().multiply(HIGH_SEASON_FACTOR));
    40	        }
    41	        return room.nightlyRate();
    42	    }
    43	}
