     5	import java.math.BigDecimal;
     6	import java.time.LocalDate;
     7	import java.time.YearMonth;
     8	import java.util.Comparator;
     9	import java.util.List;
    10	
    11	/** Relatórios em CSV (uma linha por registro, "\n" no fim de cada). */
    12	public final class Reports {
    13	
    14	    private Reports() {
    15	    }
    16	
    17	    public static String occupancy(LocalDate night, List<Reservation> reservations, List<Room> rooms) {
    18	        List<Reservation> occupying = reservations.stream()
    19	                .filter(r -> r.status().isPaid() && r.occupiesNight(night))
    20	                .sorted(Comparator.comparingInt((Reservation r) -> r.room().number()))
    21	                .toList();
    22	        StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    23	        for (Reservation r : occupying) {
    24	            RoomType type = r.room().type();
    25	            csv.append(r.room().number()).append(',').append(type).append(',').append(r.id()).append(',')
    26	                    .append(r.checkIn()).append(',').append(r.checkOut()).append('\n');
    27	        }
    28	        long occupied = occupying.stream().map(r -> r.room().number()).distinct().count();
    29	        return csv.append("total,").append(occupied).append('/').append(rooms.size()).append('\n').toString();
    30	    }
    31	
    32	    public static String revenue(YearMonth month, List<Reservation> reservations) {
    33	        List<Reservation> kept = reservations.stream()
    34	                .filter(r -> YearMonth.from(r.checkIn()).equals(month) && r.kept().signum() > 0)
    35	                .sorted(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id))
    36	                .toList();
    37	        StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    38	        BigDecimal total = Money.round(BigDecimal.ZERO);
    39	        for (Reservation r : kept) {
    40	            csv.append(r.id()).append(',').append(r.room().number()).append(',').append(r.checkIn()).append(',')
    41	                    .append(r.checkOut()).append(',').append(r.status()).append(',')
    42	                    .append(r.kept().toPlainString()).append('\n');
    43	            total = total.add(r.kept());
    44	        }
    45	        return csv.append("total,").append(total.toPlainString()).append('\n').toString();
    46	    }
