320	    10	/** Registro das formas de identificação: é o único lugar a mexer para aceitar uma nova. */
321	    11	public final class IdentificationKinds {
322	    12	
323	    13	    private static final List<IdentificationKind> KINDS = List.of(
324	    14	            new CpfIdentification.Kind(),
325	    15	            new CnpjIdentification.Kind(),
326	    16	            new PassportIdentification.Kind());
327	    17	
328	    18	    private IdentificationKinds() {
329	    19	    }
330	    20	
331	    21	    /** Todos os campos de identificação, na ordem em que aparecem no JSON. */
332	    22	    public static List<String> allFieldNames() {
333	    23	        List<String> names = new ArrayList<>();
334	    24	        KINDS.forEach(kind -> names.addAll(kind.fieldNames()));
335	    25	        return names;
336	    26	    }
337	    27	
338	    28	    /** {@code given} traz os campos presentes no corpo (valores nulos já descartados). */
339	    29	    public static Identification parse(Map<String, String> given) {
340	    30	        List<IdentificationKind> used = KINDS.stream()
341	    31	                .filter(kind -> kind.fieldNames().stream().anyMatch(given::containsKey))
342	    32	                .toList();
343	    33	        if (used.size() != 1) {
344	    34	            throw DomainException.invalidRequest(
345	    35	                    "Informe a identificação de um único jeito: " + describeKinds());
346	    36	        }
347	    37	        IdentificationKind kind = used.get(0);
348	    38	        Map<String, String> values = new LinkedHashMap<>();
349	    39	        for (String name : kind.fieldNames()) {
350	    40	            String value = given.get(name);
351	    41	            if (value == null || value.isBlank()) {
352	    42	                throw DomainException.invalidRequest("Campo obrigatório ausente: " + name);
353	    43	            }
354	    44	            values.put(name, value.trim());
355	    45	        }
356	    46	        return kind.create(values);
357	    47	    }
358	    48	
359	    49	    /** Mapa com todos os campos de identificação, null nos que não se aplicam. */
360	    50	    public static Map<String, String> withNulls(Identification identification) {
361	    51	        Map<String, String> all = new LinkedHashMap<>();
362	    52	        for (String name : allFieldNames()) {
363	    53	            all.put(name, identification.fields().get(name));
364	    54	        }
365	    55	        return all;
366	    56	    }
367	    57	
368	    58	    private static String describeKinds() {
369	    59	        return String.join(" | ", KINDS.stream().map(kind -> String.join("+", kind.fieldNames())).toList());
370	    60	    }
