    12	/** Empresa com CNPJ: recebe a fatura de hospedagem, com o ISS retido. */
    13	record CnpjIdentification(String cnpj, String companyName) implements Identification {
    14	
    15	    static final String TITLE = "Fatura de hospedagem";
    16	    private static final BigDecimal ISS_RATE = new BigDecimal("0.05");
    17	
    18	    @Override
    19	    public Map<String, String> fields() {
    20	        return Map.of("companyCnpj", cnpj, "companyName", companyName);
    21	    }
