    13	
    14	    private Reports() {
    15	    }
    16	
    17	    public static String occupancy(LocalDate night, List<Reservation> reservations, List<Room> rooms) {
    18	        List<Reservation> occupying = reservations.stream()
    19	                .filter(r -> r.status().isPaid() && r.occupiesNight(night))
    20	                .sorted(Comparator.comparingInt((Reservation r) -> r.room().number()))
    21	                .toList();
    22	        StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    23	        for (Reservation r : occupying) {
    24	            RoomType type = r.room().type();
    25	            csv.append(r.room().number()).append(',').append(type).append(',').append(r.id()).append(',')
    26	                    .append(r.checkIn()).append(',').append(r.checkOut()).append('\n');
    27	        }
    28	        long occupied = occupying.stream().map(r -> r.room().number()).distinct().count();
    29	        return csv.append("total,").append(occupied).append('/').append(rooms.size()).append('\n').toString();
    30	    }
