    32	    public static String revenue(YearMonth month, List<Reservation> reservations) {
    33	        List<Reservation> kept = reservations.stream()
    34	                .filter(r -> YearMonth.from(r.checkIn()).equals(month) && r.kept().signum() > 0)
    35	                .sorted(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id))
    36	                .toList();
    37	        StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    38	        BigDecimal total = Money.round(BigDecimal.ZERO);
    39	        for (Reservation r : kept) {
    40	            csv.append(r.id()).append(',').append(r.room().number()).append(',').append(r.checkIn()).append(',')
    41	                    .append(r.checkOut()).append(',').append(r.status()).append(',')
    42	                    .append(r.kept().toPlainString()).append('\n');
    43	            total = total.add(r.kept());
    44	        }
    45	        return csv.append("total,").append(total.toPlainString()).append('\n').toString();
    46	    }
    47	}
