    32	    public synchronized Reservation create(NewReservation request) {
    33	        if (!request.checkOut().isAfter(request.checkIn())) {
    34	            throw DomainException.invalidRequest("A saída deve ser depois da entrada");
    35	        }
    36	        if (request.guests() < 1) {
