    40	        if (request.guests() > room.capacity()) {
    41	            throw DomainException.capacityExceeded(room.capacity());
    42	        }
    43	        boolean taken = reservations.values().stream()
    44	                .anyMatch(r -> r.occupies(room.number(), request.checkIn(), request.checkOut()));
    45	        if (taken) {
    46	            throw DomainException.roomUnavailable(room.number());
    47	        }
    48	        Quote quote = Pricing.quote(room, request.checkIn(), request.checkOut(), request.ratePlan());
    49	        Reservation reservation = new Reservation(reservations.size() + 1L, room, request.guestName(),
    50	                request.guestEmail(), request.identification(), request.checkIn(), request.checkOut(),
    51	                request.guests(), request.ratePlan(), quote);
