    23	/** Rotas HTTP combinadas com o site. */
    24	public final class Api {
    25	
    26	    private static final ObjectMapper MAPPER = new ObjectMapper();
    27	    private static final String CSV = "text/csv; charset=utf-8";
    28	
    29	    private Api() {
    30	    }
    31	
    32	    public static Javalin create(ReservationService service, Outbox outbox) {
    33	        Javalin app = Javalin.create();
    34	
    35	        app.get("/rooms", ctx -> ctx.json(service.rooms().stream().map(Views::room).toList()));
    36	
    37	        app.post("/reservations", ctx ->
    38	                ctx.status(201).json(Views.reservation(service.create(parseNewReservation(ctx)))));
    39	        app.get("/reservations/{id}", ctx -> ctx.json(Views.reservation(service.get(ctx.pathParam("id")))));
    40	        app.post("/reservations/{id}/confirmation",
    41	                ctx -> ctx.json(Views.reservation(service.confirm(ctx.pathParam("id")))));
    42	        app.post("/reservations/{id}/cancellation",
    43	                ctx -> ctx.json(Views.reservation(service.cancel(ctx.pathParam("id")))));
    44	        app.post("/reservations/{id}/check-in",
    45	                ctx -> ctx.json(Views.reservation(service.checkIn(ctx.pathParam("id")))));
    46	        app.post("/reservations/{id}/check-out",
    47	                ctx -> ctx.json(Views.document(service.checkOut(ctx.pathParam("id")))));
    48	        app.get("/reservations/{id}/document",
    49	                ctx -> ctx.json(Views.document(service.document(ctx.pathParam("id")))));
    50	
    51	        app.get("/messages", ctx -> ctx.json(outbox.sent().stream().map(Views::message).toList()));
    52	
    53	        app.get("/reports/occupancy", ctx -> {
    54	            LocalDate date = parseDate(ctx.queryParam("date"), "date");
    55	            ctx.contentType(CSV).result(Reports.occupancy(date, service.all(), service.rooms()));
    56	        });
    57	        app.get("/reports/revenue", ctx -> {
    58	            YearMonth month = parseMonth(ctx.queryParam("month"));
    59	            ctx.contentType(CSV).result(Reports.revenue(month, service.all()));
    60	        });
    61	
    62	        app.exception(DomainException.class,
    63	                (e, ctx) -> ctx.status(e.status()).json(error(e.code(), e.getMessage())));
    64	        app.exception(Exception.class, (e, ctx) -> {
    65	            e.printStackTrace();
    66	            ctx.status(500).json(error("INTERNAL_ERROR", "Erro inesperado"));
    67	        });
    68	        return app;
    69	    }
    70	
    71	    private static Map<String, String> error(String code, String message) {
    72	        Map<String, String> body = new LinkedHashMap<>();
    73	        body.put("error", code);
    74	        body.put("message", message);
    75	        return body;
    76	    }
    77	
    78	    private static NewReservation parseNewReservation(Context ctx) {
    79	        JsonNode body = parseBody(ctx.body());
    80	        Map<String, String> given = new LinkedHashMap<>();
    81	        for (String name : IdentificationKinds.allFieldNames()) {
    82	            String value = optionalText(body, name);
    83	            if (value != null) {
    84	                given.put(name, value);
    85	            }
    86	        }
    87	        Identification identification = IdentificationKinds.parse(given);
    88	        return new NewReservation(
    89	                requiredInt(body, "roomNumber"),
    90	                requiredText(body, "guestName"),
    91	                requiredText(body, "guestEmail"),
    92	                identification,
    93	                parseDate(optionalText(body, "checkIn"), "checkIn"),
    94	                parseDate(optionalText(body, "checkOut"), "checkOut"),
    95	                requiredInt(body, "guests"),
    96	                parseRatePlan(requiredText(body, "ratePlan")));
    97	    }
    98	
    99	    private static JsonNode parseBody(String raw) {
   100	        try {
   101	            JsonNode node = MAPPER.readTree(raw);
   102	            if (node != null && node.isObject()) {
   103	                return node;
   104	            }
   105	        } catch (JsonProcessingException ignored) {
   106	            // cai na mensagem abaixo
   107	        }
   108	        throw DomainException.invalidRequest("O corpo deve ser um objeto JSON");
   109	    }
   110	
   111	    /** Texto do campo, ou null se ausente ou nulo; um valor que não é texto é erro. */
   112	    private static String optionalText(JsonNode body, String name) {
   113	        JsonNode node = body.get(name);
   114	        if (node == null || node.isNull()) {
   115	            return null;
   116	        }
   117	        if (!node.isTextual()) {
   118	            throw DomainException.invalidRequest("O campo " + name + " deve ser texto");
   119	        }
   120	        return node.asText();
   121	    }
   122	
   123	    private static String requiredText(JsonNode body, String name) {
   124	        String value = optionalText(body, name);
   125	        if (value == null || value.isBlank()) {
   126	            throw DomainException.invalidRequest("Campo obrigatório ausente: " + name);
   127	        }
   128	        return value.trim();
   129	    }
   130	
   131	    private static int requiredInt(JsonNode body, String name) {
   132	        JsonNode node = body.get(name);
   133	        if (node == null || !node.isInt()) {
   134	            throw DomainException.invalidRequest("O campo " + name + " deve ser um número inteiro");
   135	        }
   136	        return node.asInt();
   137	    }
   138	
   139	    private static LocalDate parseDate(String value, String name) {
   140	        if (value == null || value.isBlank()) {
   141	            throw DomainException.invalidRequest("Campo obrigatório ausente: " + name);
   142	        }
   143	        try {
   144	            return LocalDate.parse(value.trim());
   145	        } catch (DateTimeParseException e) {
   146	            throw DomainException.invalidRequest("Data inválida em " + name + ": use o formato 2027-07-10");
   147	        }
   148	    }
   149	
   150	    private static YearMonth parseMonth(String value) {
   151	        if (value == null || value.isBlank()) {
   152	            throw DomainException.invalidRequest("Parâmetro obrigatório ausente: month");
   153	        }
   154	        try {
   155	            return YearMonth.parse(value.trim());
   156	        } catch (DateTimeParseException e) {
   157	            throw DomainException.invalidRequest("Mês inválido: use o formato 2027-07");
   158	        }
   159	    }
   160	
   161	    private static RatePlan parseRatePlan(String value) {
   162	        try {
   163	            return RatePlan.valueOf(value);
   164	        } catch (IllegalArgumentException e) {
   165	            throw DomainException.invalidRequest("Plano de tarifa inválido: " + value);
   166	        }
   167	    }
   168	}
